namespace PinkMachine19.TimeClock.Domain;

public interface IClockEntryRepository
{
    void SaveClockEntry(ClockEntry clockEntry);
    IEnumerable<ClockEntry> GetEmployeeClockEntries(int employeeId, DateTime startDate, DateTime endDate);
    ClockEntry? GetOpenClockEntry(int employeeId);
}

// Change only the declaration in ClockEntryRepository.cs.
public sealed class ClockEntryRepository : IClockEntryRepository

// Append in App/Program.cs.
IClockEntryRepository repository = new ClockEntryRepository();
ClockEntry? openEntry = repository.GetOpenClockEntry(18);
Console.WriteLine(openEntry is null ? "No open entry" : "Open entry found");
